// ---------------------------------------------------------------------------

interface RepairListFilters {
  status?: string
  assignedTo?: string
  pickupDate?: 'today' | 'this_week'
  page?: number
  pageSize?: number
}

/** Get paginated repair list with optional filters. */
export async function getRepairs(filters: RepairListFilters = {}): Promise<PaginatedRepairs> {
  const params = new URLSearchParams()

  if (filters.status) params.set('status', filters.status)
  if (filters.assignedTo === 'unassigned') params.set('assignedTo', 'unassigned')
  else if (filters.assignedTo) params.set('assignedTo', filters.assignedTo)
  if (filters.pickupDate) params.set('pickupDate', filters.pickupDate)
  params.set('page', String(filters.page ?? 1))
  params.set('pageSize', String(filters.pageSize ?? 20))

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs list')
  }

  return response.json()
}

