/**
 * Complete a repair with payment data (single or split methods).
 *
 * Atomic transaction: validates → deducts stock → creates linked sale → marks completed.
 */
export async function completeRepairPayment(
  repairId: string,
  input: CompleteRepairInput,
): Promise<CompleteRepairResult> {
  const response = await fetch(`/api/repairs/${repairId}/complete`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Payment completion failed' }))
    throw new Error(error.error || `Failed to complete repair (status ${response.status})`)
  }

  return response.json() as Promise<CompleteRepairResult>
}

// ---------------------------------------------------------------------------
// Week Calendar API — GET /repairs?from=&to=&statusIn=
// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

