// ---------------------------------------------------------------------------
// Mock the hook — must be at top level for hoisting
// ---------------------------------------------------------------------------

const mockUseRepairsForWeek = vi.fn() as ReturnType<typeof vi.fn> & {
  mockReturnValue: (value: unknown) => void
}

vi.mock('../../hooks/useRepairsForWeek.js', () => ({
  useRepairsForWeek: (...args: unknown[]) => mockUseRepairsForWeek(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(id: string, plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

// Feb 2024 week: Mon Feb 5 — Sun Feb 11
const WEEK_MONDAY = 1707033600000 // Feb 5, 2024 00:00 UTC+1 approx
const TUESDAY = 1707120000000     // Feb 6
const WEDNESDAY = 1707206400000   // Feb 7

// ---------------------------------------------------------------------------
// Helper — set up the mock hook return value and render
// ---------------------------------------------------------------------------

function setupHook(repairs: RepairDetailWithCustomer[], isLoading = false) {
  const mockGoPrev = vi.fn()
  const mockGoNext = vi.fn()
  const mockGoToday = vi.fn()

  mockUseRepairsForWeek.mockReturnValue({
    repairs,
    weekStart: WEEK_MONDAY,
    weekEnd: WEEK_MONDAY + 6 * 24 * 60 * 60 * 1000 + 86399999,
    isLoading,
    error: null,
    goPrev: mockGoPrev,
    goNext: mockGoNext,
    goToday: mockGoToday,
  })

  return { mockGoPrev, mockGoNext, mockGoToday }
}

// ---------------------------------------------------------------------------
// Tests: Day columns rendering
// ---------------------------------------------------------------------------

describe('RepairCalendarView — day columns', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupHook([])
